<?php
require __DIR__.'/test-bootstrap.php';
use Modules\AiReception\Native\AgentSettings;use Modules\AiReception\Native\KnowledgeBase;use Modules\AiReception\Native\ConversationMemory;use Modules\AiReception\Native\DomainRegistry;
$n=0;function check72($x,$name){global $n;if(!$x)throw new RuntimeException($name);echo 'PASS '.++$n.' '.$name.PHP_EOL;}
if($host==='comercio'){check72(!app(Modules\AiReception\Native\Access::class)->enabled('aireception'),'traditional tenant remains without AiReception');try{app(AgentSettings::class)->privateConfiguration();throw new LogicException('Unauthorized profile');}catch(Symfony\Component\HttpKernel\Exception\HttpExceptionInterface $e){check72($e->getStatusCode()===403,'disabled tenant cannot read agent configuration');}exit;}
$token=$host==='dental'?'politicasonrisaprivada':'politicatintaprivada';$other=$host==='dental'?'politicatintaprivada':'politicasonrisaprivada';
if(($argv[3]??'')==='prepare'){app(AgentSettings::class)->save(['enabled'=>false,'mode'=>'simulated','model'=>'fixture-model','max_output_tokens'=>512,'profile'=>['business_name'=>'Negocio ficticio '.$host,'receptionist_name'=>'Recepcion '.$host,'tone'=>$host==='dental'?'formal':'cordial','locale'=>'es-PE','policies'=>$token.' Las cancelaciones se solicitan con anticipacion.']]);echo "Prepared fictional tenant profile/document\n";exit;}
$profile=app(AgentSettings::class)->publicProfile();check72($profile['business_name']==='Negocio ficticio '.$host,'tenant-specific personality persisted');$own=app(KnowledgeBase::class)->search($token);check72(count($own)>0,'own document indexed and cited');check72(app(KnowledgeBase::class)->search($other)===[],'other actual tenant document not retrieved');check72(app(DomainRegistry::class)->supportsBookings(),'verified domain adapter available');
$db->beginTransaction();try{$person=(int)$db->table('persons')->where('type','customers')->value('id');$now=date('Y-m-d H:i:s');$cid=$db->table('aireception_conversations')->insertGetId(['person_id'=>$person,'status'=>'automated','created_at'=>$now,'updated_at'=>$now]);$memory=app(ConversationMemory::class);$memory->record($cid,$person,'availability',['day'=>'2027-03-15']);check72($memory->load($cid,$person)['day']==='2027-03-15','authorized memory persists');try{$memory->load($cid,$person+100000);throw new LogicException('Foreign person memory');}catch(Symfony\Component\HttpKernel\Exception\HttpExceptionInterface $e){check72($e->getStatusCode()===404,'foreign identity cannot read memory');}}finally{$db->rollBack();}
echo "RESULT $n tenant isolation checks $host\n";
